const tabId = 2023077191;

const points = await browserjs(tabId, () => {
  const chart = document.querySelector('.byaaN') || document.querySelector('.Z2KDD');
  if (!chart) return { notFound: true };

  const rect = chart.getBoundingClientRect();
  const results = [];

  // Try 10 positions across the chart width
  for (let i = 0; i <= 10; i++) {
    const clientX = rect.left + (rect.width * i) / 10;
    const clientY = rect.top + rect.height / 2;

    chart.dispatchEvent(new MouseEvent('mousemove', {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX,
      clientY
    }));

    // Check if tooltip or hovered text appeared
    // In Google Finance, the price header updates or a tooltip element appears
    const tooltip = document.querySelector('[role="tooltip"], .hover-card, [jsname*="hover"], [jsname*="tooltip"]');
    const headerPrice = document.querySelector('.IHz7Sd')?.innerText;

    results.push({
      i,
      headerPrice,
      tooltipText: tooltip?.innerText
    });
  }

  return results;
});

