// Let's sweep across the chart horizontally and collect all distinct tooltips!
const sweepData = [];
const steps = 25;

for (let i = 0; i <= steps; i++) {
  const x = chartInfo.left + 50 + (chartInfo.width - 60) * (i / steps);
  const y = chartInfo.top + chartInfo.height / 2;

  await tool.mouse({
    tabId,
    action: "move",
    coordinate: [Math.round(x), Math.round(y)]
  });

  const tooltipText = await browserjs(tabId, () => {
    // Look for elements containing "Price:" or "Aug" or "Sep" inside .vRa8Kc
    const els = Array.from(document.querySelectorAll('.vRa8Kc *')).filter(e => e.textContent.includes('Price:'));
    return els.length > 0 ? els[els.length - 1].textContent.trim() : null;
  });

  if (tooltipText && (!sweepData.length || sweepData[sweepData.length - 1] !== tooltipText)) {
    sweepData.push(tooltipText);
  }
}

console.log("Collected tooltips:", sweepData);

const tabId = 2023077191;

// Let's inspect the exact tooltip text structure and get the date for each data point
const detailedData = [];

// The chart has transform="translate(37.40625,16)" inside the svg
// chart left is 357, so chart origin x is 357 + 37.4 = 394.4
// width of plot area is ~833px
const originX = 357 + 37.4;
const plotWidth = 832.6;

// There are 22 data points (since 832.59375 / 39.64732142857142 = 21 intervals, so 22 points, index 0 to 21)
for (let i = 0; i <= 21; i++) {
  const x = originX + i * 39.64732142857142;
  const y = 354 + 100;

  await tool.mouse({
    tabId,
    action: "move",
    coordinate: [Math.round(x), Math.round(y)]
  });

  const pointInfo = await browserjs(tabId, () => {
    // Look for the tooltip container
    const els = Array.from(document.querySelectorAll('.vRa8Kc *')).filter(e => e.textContent.includes('Price:'));
    if (els.length > 0) {
      // Find parent or container that has the date, price, volume, etc.
      let container = els[els.length - 1];
      while (container && container.parentElement && !container.textContent.includes('2026') && container !== document.body) {
        container = container.parentElement;
      }
      return container ? container.textContent.trim() : els[els.length - 1].textContent.trim();
    }
    return null;
  });

  detailedData.push({ i, pointInfo });
}

console.log(JSON.stringify(detailedData, null, 2));

const tabId = 2023077191;

const chartOriginX = 357 + 37.40625;
const step = 39.64732142857142;

const dailyData = [];

for (let k = 0; k <= 21; k++) {
  const x = Math.round(chartOriginX + k * step);
  const y = 354 + 100;

  await tool.mouse({
    tabId,
    action: "move",
    coordinate: [x, y]
  });

  // wait 50ms
  const pt = await browserjs(tabId, () => {
    // Find tooltip text inside .vRa8Kc
    const textEl = document.querySelector('.vRa8Kc [jsname="TFpDrb"]') || document.querySelector('.vRa8Kc');
    // Look for all text nodes or elements containing Price
    const all = Array.from(document.querySelectorAll('.vRa8Kc *'));
    const priceEl = all.find(e => e.textContent.includes('Price:') && e.textContent.includes('2026'));
    if (priceEl) {
      return priceEl.textContent.trim();
    }
    // Check if tooltip is anywhere in document
    const anyTooltip = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.includes('Price:'));
    if (anyTooltip) {
      return anyTooltip.parentElement?.textContent?.trim();
    }
    return null;
  });

  dailyData.push({ k, pt });
}

