for (let i = 0; i <= 21; i++) {
  const x = originX + i * 39.64732142857142;
  const y = 354 + 100;

  await tool.mouse({
    tabId,
    action: "move",
    coordinate: [Math.round(x), Math.round(y)]
  });

  const pointInfo = await browserjs(tabId, () => {
