      // Find parent or container that has the date, price, volume, etc.
      let container = els[els.length - 1];
      while (container && container.parentElement && !container.textContent.includes('2026') && container !== document.body) {
        container = container.parentElement;
      }
      return container ? container.textContent.trim() : els[els.length - 1].textContent.trim();
    }
